  private fun decodeParam(id: Int, m: PParam, child: (Int) -> Ast.AstNode): Ast.Param =
    Ast.Param(
      typeName = m.typeName,
      typeAttr = Ast.TypeAttr.valueOf(m.typeAttr.name.removePrefix("TYPE_ATTR_")),
