  private fun decodeSubClassDef(id: Int, m: PSubClassDef, child: (Int) -> Ast.AstNode): Ast.SubClassDef =
    Ast.SubClassDef(
      name = m.name,
      params = if (m.paramsPresent) m.paramsList.map { child(it) as Ast.Param } else null,
      nodeId = id,
      start = m.start,
      end = m.end,
