  private fun decodeTupleDef(id: Int, m: PTupleDef, child: (Int) -> Ast.AstNode): Ast.TupleDef =
    Ast.TupleDef(
      body = m.bodyList.map { child(it) as Ast.Param },
      nodeId = id,
      start = m.start,
      end = m.end,
