      return id
    }

    fun encodeModuleDef(node: Ast.ModuleDef): Int {
      val defsVals = node.defs.map { encodeSuperClassDef(it) }
      val id = alloc()
      nodes.add(
        PNodeEntry.newBuilder().setId(id).setModuleDef(
          PModuleDef.newBuilder()
            .setName(node.name)
            .addAllDefs(defsVals)
            .setStart(node.start)
            .setEnd(node.end)
            .build()
        ).build()
      )
      return id
    }

    fun encodeParam(node: Ast.Param): Int {
      val id = alloc()
      nodes.add(
        PNodeEntry.newBuilder().setId(id).setParam(
          PParam.newBuilder()
            .setTypeName(node.typeName)
            .setTypeAttr(PTypeAttr.valueOf("TYPE_ATTR_" + node.typeAttr.name))
            .setName(node.name)
            .setStart(node.start)
            .setEnd(node.end)
            .build()
        ).build()
      )
      return id
    }

    fun encodeSealedClassDefs(node: Ast.SealedClassDefs): Int {
      val subsVals = node.subs.map { encodeSubClassDef(it) }
      val id = alloc()
      nodes.add(
        PNodeEntry.newBuilder().setId(id).setSealedClassDefs(
          PSealedClassDefs.newBuilder()
            .addAllSubs(subsVals)
            .setStart(node.start)
            .setEnd(node.end)
            .build()
        ).build()
      )
      return id
    }

    fun encodeSubClassDef(node: Ast.SubClassDef): Int {
      val paramsVals = node.params?.let { xs -> xs.map { encodeParam(it) } } ?: emptyList()
      val id = alloc()
      nodes.add(
        PNodeEntry.newBuilder().setId(id).setSubClassDef(
          PSubClassDef.newBuilder()
            .setName(node.name)
            .setParamsPresent(node.params != null)
            .addAllParams(paramsVals)
            .setStart(node.start)
            .setEnd(node.end)
            .build()
        ).build()
      )
      return id
    }

    fun encodeSuperClassDef(node: Ast.SuperClassDef): Int {
      val bodyId = encodeSuperClassDefBody(node.body)
      val attrsId = node.attrs?.let { encodeAttributes(it) } ?: 0
      val id = alloc()
      nodes.add(
        PNodeEntry.newBuilder().setId(id).setSuperClassDef(
          PSuperClassDef.newBuilder()
            .setName(node.name)
            .setBody(bodyId)
            .setAttrsPresent(node.attrs != null)
            .setAttrs(attrsId)
            .setStart(node.start)
            .setEnd(node.end)
            .build()
        ).build()
      )
      return id
    }

    fun encodeTupleDef(node: Ast.TupleDef): Int {
      val bodyVals = node.body.map { encodeParam(it) }
      val id = alloc()
      nodes.add(
        PNodeEntry.newBuilder().setId(id).setTupleDef(
          PTupleDef.newBuilder()
            .addAllBody(bodyVals)
            .setStart(node.start)
            .setEnd(node.end)
            .build()
        ).build()
      )
      return id
    }

    fun encodeSuperClassDefBody(node: Ast.SuperClassDefBody): Int = when (node) {
      is Ast.SealedClassDefs -> encodeSealedClassDefs(node)
      is Ast.TupleDef -> encodeTupleDef(node)
